namespace CafeStockAI.Desktop;
internal static class FeatureCheck
{
 public static void Run(string folder)
 {
  Directory.CreateDirectory(folder); InventoryStore.TestDirectory=Path.Combine(folder,"data-"+Guid.NewGuid().ToString("N"));PageUi.Strict=true;var checks=new List<string>();
  void Assert(bool ok,string message){if(!ok)throw new InvalidOperationException(message);checks.Add(message);}
  void Deny(Action action,string message){try{action();}catch(Exception e) when(e is UnauthorizedAccessException or InvalidOperationException){checks.Add(message);return;}throw new Exception("Engellenmedi: "+message);}
  void Screenshot(Form form,string name){form.Show();if(form is IInventoryPage page)page.RefreshData();Application.DoEvents();using var bmp=new Bitmap(form.Width,form.Height);form.DrawToBitmap(bmp,form.ClientRectangle);bmp.Save(Path.Combine(folder,name+".png"));form.Hide();}
  try
  {
   string seed=Path.Combine(folder,"seed");if(Directory.Exists(seed)){Directory.CreateDirectory(InventoryStore.TestDirectory);foreach(string file in Directory.EnumerateFiles(seed,"*.json"))File.Copy(file,Path.Combine(InventoryStore.TestDirectory,Path.GetFileName(file)));}
   Assert(QuantityText.Format(12.000m)=="12"&&QuantityText.Format(7.500m)=="7.5", "Tam sayılarda ondalık sıfırlar gizli; kesirler korunuyor");Assert(QuantityText.TryParse("7.5",out var point)&&QuantityText.TryParse("7,5",out var comma)&&point==7.5m&&comma==7.5m,"Nokta ve virgülle kesirli miktar girişi");using(var input=new QuantityInput{DecimalPlaces=3,Maximum=100}){input.Value=12m;Assert(input.Text=="12","Miktar kutusu 12 gösteriyor");input.Value=7.5m;Assert(input.Text=="7.5","Miktar kutusu 7.5 gösteriyor");}
   DemoData.Initialize();int seededMovements=InventoryStore.Load().Movements.Count;DemoData.Initialize();Assert(InventoryStore.Load().Movements.Count==seededMovements,"Örnek veri ikinci açılışta çoğalmıyor");Accounts.Sync();var data=InventoryStore.Load();var products=ProductStore.Load();Assert(products.Count>=99&&products.All(p=>!string.IsNullOrWhiteSpace(p.Unit)),"Ürün kataloğu ve birimler tamam");
   Assert(Accounts.Load().Count==data.Employees.Count,"Her personel için ayrı hesap");Assert(!Accounts.Login("Canbora Baloğlu","yanlış"),"Hatalı şifre reddediliyor");Assert(Accounts.Login("canbora baloğlu","123456"),"Ad-soyad ve Türkçe harflerle giriş");Assert(Access.View().Branches.All(b=>b.Name=="Elazığ"),"Personel yalnız kendi şubesini görüyor");Deny(()=>BranchMovements.Add(products[0].Id,"İnegöl","Bar",1,"Giriş","test"),"Başka şubeye yazma engeli");Deny(()=>BranchRegistry.SaveNamedBranch(null,"Yetkisiz"),"Yetkisiz şube ekleme engeli");
   string branch="Elazığ";var draft=products.Select(p=>new BranchCountLine{ProductId=p.Id,ExpectedBar=BranchStock.Balance(data,p.Id,branch,"Bar"),ExpectedDepot=BranchStock.Balance(data,p.Id,branch,"Depo"),CountedBar=BranchStock.Balance(data,p.Id,branch,"Bar")+1,CountedDepot=BranchStock.Balance(data,p.Id,branch,"Depo")}).ToList();int movements=data.Movements.Count;BranchStock.Complete(branch,draft,"Sahte isim");data=InventoryStore.Load();var pending=data.Counts.Last();Assert(pending.Status=="Onay bekliyor"&&pending.Operator=="Canbora Baloğlu"&&data.Movements.Count==movements,"Sayım onay bekliyor; stok değişmedi; kişi oturumdan alındı");Deny(()=>Operations.Review(pending.Id,true,""),"Personel kendine onay veremiyor");
   Assert(Accounts.Login("Aslıhan Erden","123456"),"Şube müdürü giriş");Operations.Review(pending.Id,true,"Kontrol edildi");data=InventoryStore.Load();Assert(data.Counts.Single(c=>c.Id==pending.Id).Status=="Onaylandı"&&data.Movements.Count==movements+products.Count,"Onay stokları yalnız bir kez güncelliyor");Deny(()=>Operations.Review(pending.Id,true,""),"İkinci onay engeli");
   Assert(Accounts.Login("Ercan Erden","123456"),"Genel müdür giriş");Assert(Access.View().Branches.Count==4,"Genel müdür tüm şubeleri görüyor");var item=products[0];data=InventoryStore.Load();decimal before=BranchStock.Balance(data,item.Id,"Elazığ","Bar"),total=data.Movements.Where(m=>m.ProductId==item.Id).Sum(m=>m.Quantity);Operations.Transfer(item.Id,"Elazığ","Bar","İnegöl","Depo",.5m);data=InventoryStore.Load();Assert(BranchStock.Balance(data,item.Id,"Elazığ","Bar")==before-.5m&&data.Movements.Where(m=>m.ProductId==item.Id).Sum(m=>m.Quantity)==total,"Transfer kaynak/hedef tutarlılığı ve toplam stok korunumu");Deny(()=>Operations.Transfer(item.Id,"Elazığ","Bar","İnegöl","Depo",100000),"Yetersiz stokta transfer engeli");
   var stale=InventoryStore.Load().Counts.First(c=>c.Status=="Onay bekliyor"&&c.BranchName=="İnegöl");int unchanged=InventoryStore.Load().Movements.Count;Deny(()=>Operations.Review(stale.Id,true,""),"Stok değiştiğinde eski sayım onaylanmıyor");Assert(InventoryStore.Load().Movements.Count==unchanged,"Başarısız onay stok değiştirmedi");Operations.Review(stale.Id,false,"Yeni sayım gerekli");Assert(InventoryStore.Load().Counts.Single(c=>c.Id==stale.Id).Status=="Reddedildi"&&InventoryStore.Load().Movements.Count==unchanged,"Ret yalnız sayım durumunu değiştirdi");
   var model=DemandModel.Train(data,item.Id,"Elazığ");Assert(model is {SevenDays:>0,Samples:>=30},"Yerel model eğitildi ve 7 günlük tahmin üretti");File.WriteAllText(Path.Combine(folder,"model.txt"),System.Text.Json.JsonSerializer.Serialize(model));
   string zip=Operations.Backup();Assert(File.Exists(zip),"Yedek dosyası oluşturuldu");string invalid=Path.Combine(folder,"invalid.zip");using(var bad=System.IO.Compression.ZipFile.Open(invalid,System.IO.Compression.ZipArchiveMode.Create))bad.CreateEntry("inventory.json");try{Operations.Restore(invalid);throw new Exception("Geçersiz yedek kabul edildi");}catch(InvalidDataException){Assert(InventoryStore.Load().Movements.Count==data.Movements.Count,"Geçersiz yedek mevcut veriyi değiştirmedi");}
   var user=Accounts.Load().Single(a=>a.Username=="Canbora Baloğlu");Accounts.Change(user.EmployeeId,"654321",false);Assert(!Accounts.Login("Canbora Baloğlu","654321"),"Kapalı hesap giriş yapamıyor");Accounts.Login("Ercan Erden","123456");Accounts.Change(user.EmployeeId,"654321",true);Assert(!Accounts.Login("Canbora Baloğlu","123456")&&Accounts.Login("Canbora Baloğlu","654321"),"Şifre yenileme eski şifreyi iptal ediyor");Accounts.Login("Ercan Erden","123456");
   Operations.Restore(zip);Assert(Access.EmployeeId is null&&Accounts.Login("Canbora Baloğlu","123456"),"Yedekten geri yükleme ve oturum yenileme");Accounts.Login("Ercan Erden","123456");
   using(var f=new FrmProducts())Screenshot(f,"urunler");using(var f=new FrmOperations()){Screenshot(f,"islemler");var tab=f.Controls.OfType<TableLayoutPanel>().Single().Controls.OfType<TabControl>().Single();for(int i=1;i<tab.TabCount;i++){tab.SelectedIndex=i;Screenshot(f,"yonetim-"+i);}}using(var f=new FrmAnalysis())Screenshot(f,"tahmin");using(var f=new FrmDashboard()){f.CheckAllPages();Screenshot(f,"panel");}
   File.WriteAllLines(Path.Combine(folder,"result.txt"),checks.Append("TÜM KONTROLLER GEÇTİ"));
  }
  catch(Exception e){File.WriteAllLines(Path.Combine(folder,"result.txt"),checks.Append(e.ToString()));Environment.ExitCode=1;}
  finally{Access.EmployeeId=null;InventoryStore.TestDirectory=null;PageUi.Strict=false;}
 }
}
